SELECT t.rec_id AS record_id,t."业务对象" AS "业务对象",t."创建时间" AS "创建时间",t."变更摘要" AS "变更摘要",t."影响记录" AS "影响记录",t."操作人" AS "操作人",t."操作类型" AS "操作类型",t."操作编号" AS "操作编号",(t."结果").name AS "结果" FROM "ActivityLog" AS t INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|audit.read|%')) ORDER BY t.rec_id ASC LIMIT 500 OFFSET $1